import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";

type PipelineLastResult = {
  returncode?: number | null;
  stdout?: string;
  stderr?: string;
  started_at?: string;
  finished_at?: string;
  duration_seconds?: number;
  material_count?: number;
  asset_count?: number;
  output_count?: number;
  variant_count?: number;
};

type PipelineStatus = {
  running?: boolean;
  current_step?: string;
  step?: string;
  material_count?: number;
  asset_count?: number;
  output_count?: number;
  variant_count?: number;
  runtime_seconds?: number;
  started_at?: string;
  updated_at?: string;
  last_result?: PipelineLastResult | null;
};

type RawOutputFile =
  | string
  | {
      id?: string | number;
      name?: string;
      filename?: string;
      file_name?: string;
      basename?: string;
      path?: string;
      url?: string;
      size?: number | string;
      size_bytes?: number | string;
      bytes?: number | string;
      type?: string;
      mime?: string;
      mime_type?: string;
      content_type?: string;
      extension?: string;
      ext?: string;
      modified_at?: string;
      updated_at?: string;
      created_at?: string;
    };

type MaterialsApiResponse =
  | RawOutputFile[]
  | {
      materials?: RawOutputFile[];
      files?: RawOutputFile[];
      items?: RawOutputFile[];
      data?: RawOutputFile[];
      outputs?: RawOutputFile[];
      output_files?: RawOutputFile[];
      total?: number;
    };

type OutputFile = {
  id: string;
  name: string;
  path?: string;
  sizeBytes: number;
  extension: string;
  typeLabel: string;
  typeKey: "image" | "video" | "audio" | "document" | "archive" | "unknown";
  modifiedAt?: string;
};

type BroadcastState = {
  isLive: boolean;
  liveStartedAt: number | null;
  currentMaterialName: string;
  ttsStatus: "idle" | "speaking" | "queued" | "error";
};

const API = {
  run: "/api/pipeline/run",
  status: "/api/pipeline/status",
  outputs: "/api/materials",
};

function getArrayFromMaterials(payload: MaterialsApiResponse): RawOutputFile[] {
  if (Array.isArray(payload)) return payload;
  if (Array.isArray(payload.outputs)) return payload.outputs;
  if (Array.isArray(payload.output_files)) return payload.output_files;
  if (Array.isArray(payload.materials)) return payload.materials;
  if (Array.isArray(payload.files)) return payload.files;
  if (Array.isArray(payload.items)) return payload.items;
  if (Array.isArray(payload.data)) return payload.data;
  return [];
}

function getBaseName(value: string): string {
  const normalized = value.replaceAll("\\", "/");
  const parts = normalized.split("/").filter(Boolean);
  return parts.at(-1) || value;
}

function toNumber(value: number | string | undefined | null): number {
  if (typeof value === "number" && Number.isFinite(value)) return value;

  if (typeof value === "string") {
    const parsed = Number(value);
    if (Number.isFinite(parsed)) return parsed;
  }

  return 0;
}

function getExtensionFromName(name: string): string {
  const clean = name.split("?")[0]?.split("#")[0] || name;
  const lastDot = clean.lastIndexOf(".");

  if (lastDot < 0 || lastDot === clean.length - 1) return "unknown";

  return clean.slice(lastDot + 1).toLowerCase();
}

function inferOutputType(
  extension: string,
  mimeLike?: string
): {
  typeKey: OutputFile["typeKey"];
  typeLabel: string;
} {
  const ext = extension.toLowerCase();
  const mime = (mimeLike || "").toLowerCase();

  if (
    mime.startsWith("image/") ||
    ["jpg", "jpeg", "png", "webp", "gif", "svg", "bmp", "avif"].includes(ext)
  ) {
    return {
      typeKey: "image",
      typeLabel: "图片产出",
    };
  }

  if (
    mime.startsWith("video/") ||
    ["mp4", "mov", "m4v", "avi", "mkv", "webm", "flv"].includes(ext)
  ) {
    return {
      typeKey: "video",
      typeLabel: "视频产出",
    };
  }

  if (
    mime.startsWith("audio/") ||
    ["mp3", "wav", "aac", "m4a", "flac", "ogg"].includes(ext)
  ) {
    return {
      typeKey: "audio",
      typeLabel: "音频产出",
    };
  }

  if (["txt", "md", "json", "csv", "xlsx", "xls", "doc", "docx", "pdf"].includes(ext)) {
    return {
      typeKey: "document",
      typeLabel: "文档产出",
    };
  }

  if (["zip", "rar", "7z", "tar", "gz"].includes(ext)) {
    return {
      typeKey: "archive",
      typeLabel: "压缩产出",
    };
  }

  return {
    typeKey: "unknown",
    typeLabel: "未知产出",
  };
}

function normalizeOutputFile(raw: RawOutputFile, index: number): OutputFile {
  if (typeof raw === "string") {
    const name = getBaseName(raw);
    const extension = getExtensionFromName(name);
    const inferred = inferOutputType(extension);

    return {
      id: `${raw}-${index}`,
      name,
      path: raw,
      sizeBytes: 0,
      extension,
      ...inferred,
    };
  }

  const rawName =
    raw.name ||
    raw.filename ||
    raw.file_name ||
    raw.basename ||
    raw.path ||
    raw.url ||
    `output-${index + 1}`;

  const name = getBaseName(String(rawName));
  const extension = String(raw.extension || raw.ext || getExtensionFromName(name)).toLowerCase();
  const mimeLike = raw.mime || raw.mime_type || raw.content_type || raw.type;
  const inferred = inferOutputType(extension, mimeLike);

  return {
    id: String(raw.id || raw.path || raw.url || name || index),
    name,
    path: raw.path || raw.url,
    sizeBytes: toNumber(raw.size_bytes ?? raw.bytes ?? raw.size),
    extension,
    modifiedAt: raw.modified_at || raw.updated_at || raw.created_at,
    ...inferred,
  };
}

function formatBytes(bytes: number): string {
  if (!bytes || bytes <= 0) return "0 B";

  const units = ["B", "KB", "MB", "GB", "TB"];
  let value = bytes;
  let unitIndex = 0;

  while (value >= 1024 && unitIndex < units.length - 1) {
    value /= 1024;
    unitIndex += 1;
  }

  const precision = value >= 10 || unitIndex === 0 ? 0 : 1;
  return `${value.toFixed(precision)} ${units[unitIndex]}`;
}

function formatDuration(seconds?: number | null): string {
  if (seconds == null || Number.isNaN(seconds)) return "--:--";

  const safeSeconds = Math.max(0, Math.floor(seconds));
  const h = Math.floor(safeSeconds / 3600);
  const m = Math.floor((safeSeconds % 3600) / 60);
  const s = safeSeconds % 60;

  if (h > 0) {
    return `${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}`;
  }

  return `${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}`;
}

function formatLiveDuration(ts: number | null): string {
  if (!ts) return "--:--";
  return formatDuration(Math.floor((Date.now() - ts) / 1000));
}

function parseCountFromText(text: string | undefined, patterns: RegExp[]): number | undefined {
  if (!text) return undefined;

  for (const pattern of patterns) {
    const match = text.match(pattern);
    if (match?.[1]) {
      const value = Number(match[1]);
      if (Number.isFinite(value)) return value;
    }
  }

  return undefined;
}

function readNumber(...values: Array<number | undefined | null>): number {
  for (const value of values) {
    if (typeof value === "number" && Number.isFinite(value)) {
      return value;
    }
  }

  return 0;
}

function getMaterialCount(status: PipelineStatus | null, outputFiles: OutputFile[]): number {
  const stdout = status?.last_result?.stdout;

  return readNumber(
    status?.material_count,
    status?.asset_count,
    status?.output_count,
    status?.last_result?.material_count,
    status?.last_result?.asset_count,
    status?.last_result?.output_count,
    parseCountFromText(stdout, [
      /material(?:s)?[_\s-]*count["']?\s*[:=]\s*(\d+)/i,
      /asset(?:s)?[_\s-]*count["']?\s*[:=]\s*(\d+)/i,
      /output(?:s)?[_\s-]*count["']?\s*[:=]\s*(\d+)/i,
      /素材(?:数|数量)?\s*[:：=]\s*(\d+)/i,
      /产出(?:数|数量)?\s*[:：=]\s*(\d+)/i,
      /产物(?:数|数量)?\s*[:：=]\s*(\d+)/i,
    ]),
    outputFiles.length
  );
}

function getVariantCount(status: PipelineStatus | null): number {
  const stdout = status?.last_result?.stdout;

  return readNumber(
    status?.variant_count,
    status?.last_result?.variant_count,
    parseCountFromText(stdout, [
      /variant(?:s)?[_\s-]*count["']?\s*[:=]\s*(\d+)/i,
      /变体(?:数|数量)?\s*[:：=]\s*(\d+)/i,
    ])
  );
}

function getRuntimeSeconds(status: PipelineStatus | null): number | undefined {
  if (!status) return undefined;

  if (typeof status.runtime_seconds === "number") {
    return status.runtime_seconds;
  }

  if (typeof status.last_result?.duration_seconds === "number") {
    return status.last_result.duration_seconds;
  }

  if (status.started_at) {
    const started = new Date(status.started_at).getTime();
    if (Number.isFinite(started)) {
      return Math.max(0, Math.floor((Date.now() - started) / 1000));
    }
  }

  if (status.last_result?.started_at && status.last_result?.finished_at) {
    const started = new Date(status.last_result.started_at).getTime();
    const finished = new Date(status.last_result.finished_at).getTime();

    if (Number.isFinite(started) && Number.isFinite(finished)) {
      return Math.max(0, Math.floor((finished - started) / 1000));
    }
  }

  return undefined;
}

function getCurrentStep(status: PipelineStatus | null): string {
  if (!status) return "等待启动";

  if (status.running) {
    return status.current_step || status.step || "管线运行中";
  }

  const returncode = status.last_result?.returncode;

  if (returncode === 0) return "最近一次运行成功";
  if (typeof returncode === "number" && returncode !== 0) return "最近一次运行失败";

  return status.current_step || status.step || "空闲";
}

function getPipelineHealth(status: PipelineStatus | null): {
  label: string;
  tone: "ok" | "warn" | "idle" | "running";
} {
  if (!status) {
    return {
      label: "未连接",
      tone: "warn",
    };
  }

  if (status.running) {
    return {
      label: "管线运行中",
      tone: "running",
    };
  }

  const returncode = status.last_result?.returncode;

  if (returncode === 0) {
    return {
      label: "运行成功",
      tone: "ok",
    };
  }

  if (typeof returncode === "number" && returncode !== 0) {
    return {
      label: "运行异常",
      tone: "warn",
    };
  }

  return {
    label: "待启动",
    tone: "idle",
  };
}

function getTypeBadgeClass(typeKey: OutputFile["typeKey"]): string {
  switch (typeKey) {
    case "image":
      return "border-emerald-300/25 bg-emerald-300/10 text-emerald-100";
    case "video":
      return "border-sky-300/25 bg-sky-300/10 text-sky-100";
    case "audio":
      return "border-violet-300/25 bg-violet-300/10 text-violet-100";
    case "document":
