    case "archive":
      return "border-orange-300/25 bg-orange-300/10 text-orange-100";
    default:
      return "border-white/15 bg-white/5 text-[oklch(82%_0_0)]";
  }
}

function getTypeIcon(typeKey: OutputFile["typeKey"]): string {
  switch (typeKey) {
    case "image":
      return "IMG";
    case "video":
