export default function BroadcastPage() {
  const [status, setStatus] = useState<PipelineStatus | null>(null);
  const [outputFiles, setOutputFiles] = useState<OutputFile[]>([]);
  const [broadcast, setBroadcast] = useState<BroadcastState>({
    isLive: false,
    liveStartedAt: null,
    currentMaterialName: "等待产出文件",
    ttsStatus: "idle",
  });

  const [loadingStatus, setLoadingStatus] = useState(false);
  const [loadingOutputs, setLoadingOutputs] = useState(false);
  const [startingPipeline, setStartingPipeline] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [nowTick, setNowTick] = useState(Date.now());
  const [lastLoadedAt, setLastLoadedAt] = useState<Date | null>(null);

  const abortRef = useRef<AbortController | null>(null);

  const pipelineHealth = useMemo(() => getPipelineHealth(status), [status]);
  const materialCount = useMemo(() => getMaterialCount(status, outputFiles), [status, outputFiles]);
  const variantCount = useMemo(() => getVariantCount(status), [status]);
  const runtimeSeconds = useMemo(() => getRuntimeSeconds(status), [status]);
  const currentStep = useMemo(() => getCurrentStep(status), [status]);

  const totalOutputSize = useMemo(
    () => outputFiles.reduce((sum, file) => sum + file.sizeBytes, 0),
    [outputFiles]
  );

  const latestOutputName = outputFiles[0]?.name || "等待产出文件";

  const loadRealtimeData = useCallback(async (silent = false) => {
    abortRef.current?.abort();

    const controller = new AbortController();
    abortRef.current = controller;

    try {
      if (!silent) {
        setLoadingStatus(true);
        setLoadingOutputs(true);
      }

      setError(null);

      const [statusResponse, outputsResponse] = await Promise.all([
        fetch(API.status, {
          method: "GET",
          headers: {
            Accept: "application/json",
          },
          signal: controller.signal,
        }),
        fetch(API.outputs, {
          method: "GET",
          headers: {
            Accept: "application/json",
          },
          signal: controller.signal,
        }),
      ]);

      if (!statusResponse.ok) {
        throw new Error(`状态接口异常：HTTP ${statusResponse.status}`);
      }

      if (!outputsResponse.ok) {
        throw new Error(`产出文件接口异常：HTTP ${outputsResponse.status}`);
      }

      const statusPayload = (await statusResponse.json()) as PipelineStatus;
      const outputsPayload = (await outputsResponse.json()) as MaterialsApiResponse;

      const normalizedOutputs = getArrayFromMaterials(outputsPayload)
        .map((item, index) => normalizeOutputFile(item, index))
        .sort((a, b) => {
          const aTime = a.modifiedAt ? new Date(a.modifiedAt).getTime() : 0;
          const bTime = b.modifiedAt ? new Date(b.modifiedAt).getTime() : 0;

          if (Number.isFinite(aTime) && Number.isFinite(bTime) && aTime !== bTime) {
            return bTime - aTime;
          }

          return a.name.localeCompare(b.name, "zh-Hans-CN");
        });

      setStatus(statusPayload);
      setOutputFiles(normalizedOutputs);
      setLastLoadedAt(new Date());

      const nextMaterialCount = getMaterialCount(statusPayload, normalizedOutputs);
      const nextVariantCount = getVariantCount(statusPayload);

      setBroadcast((prev) => ({
        ...prev,
        currentMaterialName:
          normalizedOutputs[0]?.name ||
          (nextMaterialCount > 0
            ? `产出文件 ${nextMaterialCount} 个 / 变体 ${nextVariantCount} 个`
            : prev.currentMaterialName),
        ttsStatus: statusPayload.running ? "queued" : prev.isLive ? "speaking" : "idle",
      }));
    } catch (err) {
      if (err instanceof DOMException && err.name === "AbortError") return;

      setError(err instanceof Error ? err.message : "无法获取真实开播数据");
    } finally {
      setLoadingStatus(false);
      setLoadingOutputs(false);
    }
  }, []);

  const startPipeline = useCallback(async () => {
    try {
      setStartingPipeline(true);
      setError(null);

      const response = await fetch(API.run, {
        method: "POST",
        headers: {
          Accept: "application/json",
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          source: "broadcast_page",
          mode: "live",
        }),
      });

      if (!response.ok) {
        throw new Error(`启动管线失败：HTTP ${response.status}`);
      }

      await loadRealtimeData(true);
    } catch (err) {
      setError(err instanceof Error ? err.message : "启动管线失败");
    } finally {
      setStartingPipeline(false);
    }
  }, [loadRealtimeData]);

  const toggleLive = useCallback(() => {
    setBroadcast((prev) => {
      const nextLive = !prev.isLive;

      return {
        ...prev,
        isLive: nextLive,
        liveStartedAt: nextLive ? Date.now() : null,
        ttsStatus: nextLive ? "speaking" : "idle",
      };
    });
  }, []);

  useEffect(() => {
    loadRealtimeData(false);

    const timer = window.setInterval(() => {
      loadRealtimeData(true);
    }, 3000);

    return () => {
      window.clearInterval(timer);
      abortRef.current?.abort();
    };
  }, [loadRealtimeData]);

  useEffect(() => {
    const timer = window.setInterval(() => {
      setNowTick(Date.now());
    }, 1000);

    return () => window.clearInterval(timer);
  }, []);

  const lastStdout = status?.last_result?.stdout?.trim();
  const lastStderr = status?.last_result?.stderr?.trim();

  return (
    <main className="min-h-screen bg-[oklch(7%_0.006_95)] text-[oklch(88%_0_0)]">
      <div className="pointer-events-none fixed inset-0 overflow-hidden">
        <div className="absolute -left-40 top-0 h-96 w-96 rounded-full bg-[oklch(84%_0.19_80/0.12)] blur-3xl" />
        <div className="absolute bottom-0 right-0 h-[32rem] w-[32rem] rounded-full bg-[oklch(77%_0.13_82/0.10)] blur-3xl" />
        <div className="absolute inset-x-0 top-0 h-px bg-[linear-gradient(90deg,transparent,oklch(84%_0.19_80/0.42),transparent)]" />
      </div>

      <section className="relative mx-auto max-w-7xl px-6 py-8 lg:px-8">
        <header className="mb-8 flex flex-col gap-5 lg:flex-row lg:items-end lg:justify-between">
          <div>
            <div className="mb-3 flex flex-wrap items-center gap-3">
              <StatusPill tone={pipelineHealth.tone}>{pipelineHealth.label}</StatusPill>
              {loadingStatus || loadingOutputs ? <StatusPill tone="idle">同步中</StatusPill> : null}
              {lastLoadedAt ? (
                <StatusPill tone="idle">最近同步 {lastLoadedAt.toLocaleTimeString()}</StatusPill>
              ) : null}
            </div>

            <h1 className="text-4xl font-semibold tracking-tight text-[oklch(91%_0_0)]">
              PHS 一键开播
            </h1>

            <p className="mt-3 max-w-2xl text-sm leading-6 text-[oklch(72%_0_0)]">
              启动真实素材管线，轮询管线状态，并通过{" "}
              <span className="font-medium text-[oklch(91%_0.06_84)]">GET /api/materials</span>{" "}
              展示 runtime/outputs/ 的真实产出文件名与大小。
            </p>
          </div>

          <div className="flex flex-wrap gap-3">
            <button
              type="button"
              onClick={startPipeline}
              disabled={startingPipeline || Boolean(status?.running)}
              className={[
                "rounded-2xl px-5 py-3 text-sm font-semibold transition",
                "bg-[oklch(84%_0.19_80)] text-[oklch(8%_0.006_95)] shadow-[0_16px_42px_oklch(84%_0.19_80/0.22)]",
                "hover:bg-[oklch(86%_0.07_84)] active:bg-[oklch(77%_0.13_82)]",
                "disabled:cursor-not-allowed disabled:opacity-45",
              ].join(" ")}
            >
              {startingPipeline ? "启动中..." : status?.running ? "管线运行中" : "启动素材管线"}
            </button>

            <button
              type="button"
              onClick={() => loadRealtimeData(true)}
              disabled={loadingStatus || loadingOutputs}
              className="rounded-2xl border border-[oklch(84%_0.19_80/0.42)] bg-[oklch(84%_0.19_80/0.10)] px-5 py-3 text-sm font-semibold text-[oklch(91%_0.06_84)] transition hover:bg-[oklch(84%_0.19_80/0.15)] disabled:cursor-not-allowed disabled:opacity-45"
            >
              刷新产出
            </button>

            <button
              type="button"
              onClick={toggleLive}
              className={[
                "rounded-2xl border px-5 py-3 text-sm font-semibold transition",
                broadcast.isLive
                  ? "border-red-400/40 bg-red-400/10 text-red-100 hover:bg-red-400/15"
                  : "border-white/10 bg-white/5 text-[oklch(91%_0_0)] hover:bg-white/10",
              ].join(" ")}
            >
              {broadcast.isLive ? "停止直播" : "开始直播"}
            </button>
          </div>
        </header>

        {error ? (
          <div className="mb-6 rounded-3xl border border-red-400/30 bg-red-400/10 px-5 py-4 text-sm text-red-100">
            {error}
          </div>
        ) : null}

        <div className="grid grid-cols-1 gap-5 md:grid-cols-2 xl:grid-cols-5">
          <MetricCard
            label="产出文件数"
            value={outputFiles.length}
            hint="来自 runtime/outputs/"
            emphasis
          />
          <MetricCard
            label="产出总大小"
            value={formatBytes(totalOutputSize)}
            hint="按文件 size 汇总"
            emphasis
          />
          <MetricCard
            label="真实素材数"
            value={materialCount}
            hint="状态接口 + 产出文件兜底"
          />
          <MetricCard
            label="真实变体数"
            value={variantCount}
            hint="来自管线状态"
          />
          <MetricCard
            label="管线运行时间"
            value={formatDuration(runtimeSeconds)}
            hint={status?.running ? "当前运行中" : "最近一次运行耗时"}
          />
        </div>

        <div className="mt-6 grid grid-cols-1 gap-6 xl:grid-cols-[1.25fr_0.75fr]">
          <section className="overflow-hidden rounded-[2rem] border border-[oklch(22%_0.018_95)] bg-[oklch(11%_0.006_95)] shadow-[0_24px_80px_rgba(0,0,0,0.28)]">
            <div className="flex items-center justify-between border-b border-white/10 px-5 py-4">
              <div>
                <h2 className="text-lg font-semibold text-[oklch(91%_0_0)]">OBS 预览</h2>
                <p className="mt-1 text-xs text-[oklch(72%_0_0)]">
                  当前展示最新产出文件：{latestOutputName}
                </p>
              </div>

              <StatusPill tone={broadcast.isLive ? "running" : "idle"}>
                {broadcast.isLive ? "LIVE" : "STANDBY"}
              </StatusPill>
            </div>

            <div className="relative aspect-video bg-[radial-gradient(circle_at_50%_40%,oklch(24%_0.035_90),oklch(5%_0.006_95)_72%)]">
              <div className="absolute inset-0 bg-[linear-gradient(135deg,transparent,oklch(84%_0.19_80/0.08),transparent)]" />

              <div className="absolute left-5 top-5 rounded-full border border-white/15 bg-black/30 px-3 py-1 text-xs text-white/80 backdrop-blur">
                OBS PREVIEW
              </div>

              <div className="absolute right-5 top-5 rounded-full border border-[oklch(84%_0.19_80/0.35)] bg-[oklch(84%_0.19_80/0.12)] px-3 py-1 text-xs text-[oklch(91%_0.06_84)] backdrop-blur">
                {currentStep}
              </div>

              <div className="absolute inset-0 flex flex-col items-center justify-center px-8 text-center">
                <div className="text-6xl font-black tracking-[0.18em] text-[oklch(91%_0_0)] drop-shadow-[0_10px_40px_rgba(0,0,0,0.65)]">
                  LIVE
                </div>

                <div className="mt-4 max-w-xl rounded-2xl border border-white/10 bg-black/30 px-5 py-3 text-sm text-[oklch(82%_0_0)] backdrop-blur">
                  {broadcast.currentMaterialName}
                </div>
              </div>

              <div className="absolute bottom-5 left-5 right-5 grid grid-cols-2 gap-3 md:grid-cols-4">
                <div className="rounded-2xl border border-white/10 bg-black/30 p-3 backdrop-blur">
                  <div className="text-xs text-white/55">产出文件</div>
                  <div className="mt-1 text-lg font-semibold text-white">{outputFiles.length}</div>
                </div>

                <div className="rounded-2xl border border-white/10 bg-black/30 p-3 backdrop-blur">
                  <div className="text-xs text-white/55">总大小</div>
                  <div className="mt-1 text-lg font-semibold text-white">
                    {formatBytes(totalOutputSize)}
                  </div>
                </div>

                <div className="rounded-2xl border border-white/10 bg-black/30 p-3 backdrop-blur">
                  <div className="text-xs text-white/55">TTS</div>
                  <div className="mt-1 text-lg font-semibold text-white">
                    {broadcast.ttsStatus === "speaking"
                      ? "播报中"
                      : broadcast.ttsStatus === "queued"
                        ? "排队中"
                        : broadcast.ttsStatus === "error"
                          ? "异常"
                          : "空闲"}
                  </div>
                </div>

                <div className="rounded-2xl border border-white/10 bg-black/30 p-3 backdrop-blur">
                  <div className="text-xs text-white/55">直播时长</div>
                  <div className="mt-1 text-lg font-semibold text-white">
                    {formatLiveDuration(broadcast.liveStartedAt)}
                  </div>
                </div>
              </div>
            </div>
          </section>

          <aside className="space-y-6">
            <section className="rounded-[2rem] border border-[oklch(22%_0.018_95)] bg-[oklch(11%_0.006_95)] p-5 shadow-[0_24px_80px_rgba(0,0,0,0.24)]">
              <h2 className="text-lg font-semibold text-[oklch(91%_0_0)]">当前步骤</h2>

              <div className="mt-5 rounded-3xl border border-[oklch(84%_0.19_80/0.28)] bg-[oklch(84%_0.19_80/0.08)] p-5">
                <div className="text-sm text-[oklch(72%_0_0)]">Pipeline Step</div>
                <div className="mt-2 text-2xl font-semibold leading-tight text-[oklch(91%_0.06_84)]">
                  {currentStep}
                </div>
              </div>

              <div className="mt-5 space-y-3 text-sm">
                <div className="flex items-center justify-between border-b border-white/10 pb-3">
                  <span className="text-[oklch(72%_0_0)]">运行状态</span>
                  <span className="font-medium text-[oklch(91%_0_0)]">
                    {status?.running ? "运行中" : "空闲"}
                  </span>
                </div>

                <div className="flex items-center justify-between border-b border-white/10 pb-3">
                  <span className="text-[oklch(72%_0_0)]">返回码</span>
                  <span className="font-medium text-[oklch(91%_0_0)]">
                    {status?.last_result?.returncode ?? "--"}
                  </span>
                </div>

                <div className="flex items-center justify-between border-b border-white/10 pb-3">
                  <span className="text-[oklch(72%_0_0)]">轮询频率</span>
                  <span className="font-medium text-[oklch(91%_0_0)]">3 秒</span>
                </div>

                <div className="flex items-center justify-between">
                  <span className="text-[oklch(72%_0_0)]">本地刷新</span>
                  <span className="font-medium text-[oklch(91%_0_0)]">
                    {new Date(nowTick).toLocaleTimeString()}
                  </span>
                </div>
              </div>
            </section>

            <section className="rounded-[2rem] border border-[oklch(22%_0.018_95)] bg-[oklch(11%_0.006_95)] p-5 shadow-[0_24px_80px_rgba(0,0,0,0.24)]">
              <h2 className="text-lg font-semibold text-[oklch(91%_0_0)]">直播控制</h2>

              <div className="mt-5 grid grid-cols-2 gap-3">
                <button
                  type="button"
                  onClick={startPipeline}
                  disabled={startingPipeline || Boolean(status?.running)}
                  className="rounded-2xl border border-[oklch(84%_0.19_80/0.35)] bg-[oklch(84%_0.19_80/0.10)] px-4 py-4 text-sm font-semibold text-[oklch(91%_0.06_84)] transition hover:bg-[oklch(84%_0.19_80/0.16)] disabled:cursor-not-allowed disabled:opacity-45"
                >
                  生成素材
                </button>

                <button
                  type="button"
                  onClick={toggleLive}
                  className="rounded-2xl border border-white/10 bg-white/5 px-4 py-4 text-sm font-semibold text-[oklch(91%_0_0)] transition hover:bg-white/10"
                >
                  {broadcast.isLive ? "停播" : "开播"}
                </button>
              </div>

              <div className="mt-5 rounded-3xl border border-white/10 bg-black/20 p-4">
                <div className="text-xs text-[oklch(72%_0_0)]">当前产出文件</div>
                <div className="mt-2 truncate text-sm font-medium leading-6 text-[oklch(91%_0_0)]">
                  {latestOutputName}
                </div>
              </div>
            </section>
          </aside>
        </div>

        <section className="mt-6 rounded-[2rem] border border-[oklch(22%_0.018_95)] bg-[oklch(11%_0.006_95)] p-5 shadow-[0_24px_80px_rgba(0,0,0,0.24)]">
          <div className="mb-5 flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between">
            <div>
              <h2 className="text-xl font-semibold tracking-tight text-[oklch(91%_0_0)]">
                真实产出文件
              </h2>
              <p className="mt-1 text-sm text-[oklch(72%_0_0)]">
                读取 runtime/outputs/ 文件列表，展示真实文件名与大小。
              </p>
            </div>

            <StatusPill tone="idle">{outputFiles.length} files</StatusPill>
          </div>

          {loadingOutputs && outputFiles.length === 0 ? (
            <OutputSkeleton />
          ) : outputFiles.length > 0 ? (
            <div className="grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-3">
              {outputFiles.map((file) => (
                <OutputFileCard key={file.id} file={file} />
              ))}
            </div>
          ) : (
            <div className="flex min-h-[240px] flex-col items-center justify-center rounded-[1.75rem] border border-dashed border-[oklch(32%_0.018_95)] bg-black/20 px-6 text-center">
              <div className="flex h-16 w-16 items-center justify-center rounded-3xl border border-[oklch(84%_0.19_80/0.28)] bg-[oklch(84%_0.19_80/0.10)] text-sm font-black tracking-wider text-[oklch(91%_0.06_84)]">
                EMPTY
              </div>

              <h3 className="mt-5 text-lg font-semibold text-[oklch(91%_0_0)]">
                runtime/outputs/ 暂无产出文件
              </h3>

              <p className="mt-2 max-w-md text-sm leading-6 text-[oklch(72%_0_0)]">
                点击“启动素材管线”后，后端通过{" "}
                <span className="font-medium text-[oklch(91%_0.06_84)]">/api/materials</span>{" "}
                返回真实产出文件即可显示在这里。
              </p>
            </div>
          )}
        </section>

        <section className="mt-6 rounded-[2rem] border border-[oklch(22%_0.018_95)] bg-[oklch(11%_0.006_95)] p-5 shadow-[0_24px_80px_rgba(0,0,0,0.24)]">
          <div className="flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between">
            <div>
              <h2 className="text-lg font-semibold text-[oklch(91%_0_0)]">最近一次管线输出</h2>
              <p className="mt-1 text-xs text-[oklch(72%_0_0)]">
                用于快速排查素材生成、变体渲染与文件落盘问题。
              </p>
            </div>

            <StatusPill tone={pipelineHealth.tone}>{pipelineHealth.label}</StatusPill>
          </div>

          <div className="mt-5 grid grid-cols-1 gap-4 lg:grid-cols-2">
            <div className="rounded-3xl border border-white/10 bg-black/25 p-4">
              <div className="mb-3 text-xs font-semibold uppercase tracking-[0.18em] text-[oklch(84%_0.19_80)]">
                STDOUT
              </div>

              <pre className="max-h-72 overflow-auto whitespace-pre-wrap break-words text-xs leading-6 text-[oklch(82%_0_0)]">
                {lastStdout || "暂无 stdout 输出"}
              </pre>
            </div>

            <div className="rounded-3xl border border-white/10 bg-black/25 p-4">
              <div className="mb-3 text-xs font-semibold uppercase tracking-[0.18em] text-red-200">
                STDERR
              </div>

              <pre className="max-h-72 overflow-auto whitespace-pre-wrap break-words text-xs leading-6 text-[oklch(82%_0_0)]">
                {lastStderr || "暂无 stderr 输出"}
              </pre>
            </div>
          </div>
        </section>
      </section>
    </main>
  );
}
